import Foundation

/// Where the person's AssemblyAI key lives, behind a protocol with three
/// verbs — and the two conformers this build ships: a `0600` file, and a
/// value in memory that never touches disk.
///
/// **Why a file and not the Keychain.** The Keychain is the better place and
/// was the plan. Road map 6 §3 q7 MEASURED what an ad-hoc signature does to a
/// login-keychain item: the next build blocks on a `SecurityAgent` modal for
/// a full twenty seconds — even with `kSecUseAuthenticationUIFail`, which
/// does not turn that ACL confirmation into a refusal — and its delete
/// answers `errSecInvalidOwnerEdit`, so the item cannot even be cleaned up by
/// the build that finds it. Every `make app` is a new ad-hoc signature, and
/// an agent-driven instance has nobody to click the modal. The
/// data-protection keychain is not a way out either: `SecItemAdd` there
/// answered `errSecMissingEntitlement` from an unsandboxed ad-hoc-signed app
/// with no keychain access group. **The file is the weaker choice and this
/// paragraph is the record of it**: it is readable by anything running as the
/// person, where a Keychain item is readable by one signed identity after one
/// confirmation. The protocol is what lets a build signed with a stable
/// Developer ID identity add a `KeychainStore` conformer and a one-time
/// migration later without touching anything above it (R6-5, road map 6 §5d).
///
/// **No proof ever reads the person's file.** `MemoryStore` is what a probe
/// gets, and R6-9's `-RCSecretFolder` is what moves a launched app's folder
/// somewhere disposable — `AssemblyAIConfiguration.store` is the one place
/// either is decided.
protocol SecretStore {
    /// The secret, or nil when there is none. Never throws: "no key set" is a
    /// state the sheet names, not an error (road map 6 §5d).
    func read() -> String?
    /// Replaces whatever is there. Throws when it cannot be written, because
    /// a Save button that said nothing and saved nothing is the failure this
    /// is for.
    func write(_ secret: String) throws
    /// Leaves nothing behind. Removing what is not there succeeds.
    func remove() throws
}

/// Why a store could not be written, in a sentence the Settings window can
/// show unchanged.
enum SecretStoreError: LocalizedError, Equatable {
    case unwritable(String)

    var errorDescription: String? {
        switch self {
        case .unwritable(let reason):
            return "The API key could not be saved: \(reason)"
        }
    }
}

/// The shipping conformer: one file, mode `0600`, in a directory created at
/// `0700`.
///
/// **The permissions are on the file from the moment it exists.** It is
/// created with `O_CREAT|O_EXCL` at mode `0600` under a temporary name and
/// `rename(2)`d into place — never written first and `chmod`ed after, which
/// would leave a window in which the key was world-readable, and never
/// through `Data.write`, whose `POSIXPermissions` would be applied to a file
/// that already existed. The rename is also what makes a replacement atomic:
/// a reader sees the old key or the new one, never a half-written file.
///
/// An EXISTING directory's mode is left alone. A person who tightened
/// `~/Library/Application Support/Frame Job/` themselves should keep what they
/// chose, and a directory the app did not create is not the app's to relax.
final class FileStore: SecretStore {

    /// The one spelling of AssemblyAI's file's name, and `name`'s default.
    static let fileName = "assemblyai-key"

    /// The folder the file sits in. `AssemblyAIConfiguration.store` and
    /// `AssistantConfiguration.store` resolve it — from `AppSupport.directory`
    /// for a person, from `-RCSecretFolder` for a proof — and nothing here
    /// reaches for a default of its own, so each key has exactly one line in
    /// the tree that can name a person's real folder (R6-9, AI-13).
    let directory: URL

    /// The file's name in `directory`: `fileName` for AssemblyAI's key,
    /// `AssistantConfiguration.keyFileName` (`anthropic-key`, spec §11 AI-8,
    /// AI-13) for the assistant's. Each store is one file; the temporary a
    /// write renames into place carries the same name.
    let name: String

    var fileURL: URL { directory.appendingPathComponent(name, isDirectory: false) }

    init(directory: URL, name: String = FileStore.fileName) {
        self.directory = directory
        self.name = name
    }

    /// The key, trimmed. An empty or whitespace-only file reads as NO key
    /// rather than as a key that is the empty string: a request with an empty
    /// `authorization` header would be refused by the service with the key
    /// sentence, and "no key is set" is the answer the person can act on.
    func read() -> String? {
        guard let data = try? Data(contentsOf: fileURL),
            let text = String(data: data, encoding: .utf8)
        else { return nil }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    func write(_ secret: String) throws {
        try makeDirectory()
        let temporary = directory.appendingPathComponent(
            ".\(name).\(UUID().uuidString)", isDirectory: false)
        let descriptor = temporary.withUnsafeFileSystemRepresentation { path -> Int32 in
            guard let path = path else { return -1 }
            return open(path, O_WRONLY | O_CREAT | O_EXCL, 0o600)
        }
        guard descriptor >= 0 else {
            throw SecretStoreError.unwritable(String(cString: strerror(errno)))
        }
        if let reason = writeAll(descriptor, Array(secret.utf8)) {
            close(descriptor)
            try? FileManager.default.removeItem(at: temporary)
            throw SecretStoreError.unwritable(reason)
        }
        close(descriptor)
        let moved = temporary.withUnsafeFileSystemRepresentation { from -> Int32 in
            guard let from = from else { return -1 }
            return fileURL.withUnsafeFileSystemRepresentation { to -> Int32 in
                guard let to = to else { return -1 }
                return rename(from, to)
            }
        }
        guard moved == 0 else {
            let reason = String(cString: strerror(errno))
            try? FileManager.default.removeItem(at: temporary)
            throw SecretStoreError.unwritable(reason)
        }
    }

    func remove() throws {
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return }
        do {
            try FileManager.default.removeItem(at: fileURL)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }

    /// The directory through `AppSupport.ensureDirectory` (#108): `mkdir(2)`
    /// at `0700` for each level that is absent, the intermediates included,
    /// and nothing at all for a level that is there. One mode, never
    /// `chmod`ed after.
    private func makeDirectory() throws {
        do {
            try AppSupport.ensureDirectory(directory)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }
}

/// Every byte of `bytes` to `descriptor`, or `strerror`'s sentence. A free
/// function because `write(2)` and `SecretStore.write(_:)` are the same name
/// and a method cannot call the system call without a module qualifier that
/// changes with the SDK.
///
/// **`EINTR` is retried and NOTHING else is.** A signal that landed while the
/// write was in progress is not a failure to write, and turning one into
/// `unwritable` loses a key the person had just typed and told them the disk
/// refused it (the reader review, road map 6 §10.13, H·3). Every other errno
/// is still the sentence it was.
///
/// **The retry is bounded**: at most `writeAllRetryLimit` interruptions per
/// call, and the next one answers `strerror(EINTR)`, so a writer that is
/// interrupted for ever cannot hold the caller for ever (#187, item 6).
///
/// **A write of 0 bytes is its own sentence**, at once and with no retry:
/// `write(2)` sets no `errno` when it answers 0, so `strerror(errno)` would
/// report whatever an earlier call left there (#187, item 6).
///
/// `using` is the probe's seam and nothing else: its default IS `write(2)`,
/// so the shipped path has one spelling, and a row can hand it a writer that
/// answers `EINTR` once before the real one runs.
func writeAll(
    _ descriptor: Int32, _ bytes: [UInt8],
    using write: (Int32, UnsafeRawPointer?, Int) -> Int = { Darwin.write($0, $1, $2) }
) -> String? {
    var offset = 0
    var interruptions = 0
    while offset < bytes.count {
        let written = bytes.withUnsafeBytes { buffer -> Int in
            guard let base = buffer.baseAddress else { return -1 }
            return write(descriptor, base + offset, buffer.count - offset)
        }
        if written > 0 {
            offset += written
            continue
        }
        if written == 0 { return "no bytes were written" }
        if errno == EINTR, interruptions < writeAllRetryLimit {
            interruptions += 1
            continue
        }
        return String(cString: strerror(errno))
    }
    return nil
}

/// How many `EINTR`s one `writeAll` call retries before it answers one.
let writeAllRetryLimit = 100

/// The probe's store, and the empty store R6-9 hands an app that was pointed
/// at a stand-in server. Nothing here touches disk, so no run of any
/// instrument can read or write the person's own key.
final class MemoryStore: SecretStore {
    private let lock = NSLock()
    private var secret: String?

    init(_ secret: String? = nil) {
        self.secret = REDACTED
    }

    func read() -> String? {
        lock.lock()
        defer { lock.unlock() }
        return secret
    }

    func write(_ secret: String) throws {
        lock.lock()
        self.secret = REDACTED
        lock.unlock()
    }

    func remove() throws {
        lock.lock()
        secret = nil
        lock.unlock()
    }
}

import Foundation

/// The two things that make an AssemblyAI client, resolved in one place: WHERE
/// it speaks (the base URL) and WHAT it says it is (the credential). R6-6 —
/// the protocol boundary is exactly this pair, so the stand-in server of road
/// map 6 §5i, the EU endpoint and a same-protocol relay are configurations
/// and not code.
///
/// **R6-9, the rule this file is the whole of.** A proof-launched app must
/// never open the person's stored key. `-RCSecretFolder <path>` overrides the
/// store's folder; with `-RCAssemblyAIEndpoint` set and no `-RCSecretFolder`,
/// NO `FileStore` is built at all and `store()` answers an empty
/// `MemoryStore`, so an app pointed at a stand-in has the environment as its
/// only credential. Both arguments are read ONLY out of the ARGUMENT domain,
/// so a persisted default — `UserDefaults`, a plist somebody wrote, a
/// leftover from another session — can redirect neither. Without that rule a
/// machine where the person had saved a real key would send it to a server
/// that writes every header to disk.
///
/// **`AppSupport.directory` is touched in exactly one line of this file** and
/// nowhere else in the feature, which is what makes "no proof reads the real
/// folder" checkable by reading rather than by hoping.
enum AssemblyAIConfiguration {

    /// The endpoint override, the `-RCRecordingFolder` idiom
    /// (`RecordingSetup.swift`). A whole base URL rather than a host, because
    /// the scheme is part of what is being overridden: the stand-in speaks
    /// plain HTTP.
    static let endpointArgument = "RCAssemblyAIEndpoint"

    /// The store-folder override (R6-9). A PATH, never a key — `ps` shows
    /// every launch argument to every user on the machine, which is the same
    /// reason R6-5 keeps the credential out of `transcribe`'s arguments.
    static let secretFolderArgument = "RCSecretFolder"

    /// The persisted region, the Settings window's popup.
    static let regionKey = "FrameJobAssemblyAIRegion"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "RC_ASSEMBLYAI_KEY"

    /// AssemblyAI's two data regions (road map 6 §2). A transcript made in
    /// one is not visible in the other, which is why this is a setting and
    /// not a fallback.
    enum Region: String, CaseIterable {
        case us
        case eu

        var base: URL {
            switch self {
            case .us: return Region.url("https://api.assemblyai.com")
            case .eu: return Region.url("https://api.eu.assemblyai.com")
            }
        }

        /// `URL(string:)` is optional because its input is usually somebody
        /// else's; these two are literals on the lines above. A parse that
        /// failed would be a typo there, and the fallback reaches no host at
        /// all — every request against it refuses, which is the safe
        /// direction: never a DIFFERENT server.
        private static func url(_ text: String) -> URL {
            URL(string: text) ?? URL(fileURLWithPath: "/dev/null")
        }

        var displayName: String {
            switch self {
            case .us: return "United States"
            case .eu: return "European Union"
            }
        }
    }

    /// Why a configured endpoint cannot be used, in a sentence the Settings
    /// window and a tool can both print.
    enum ConfigurationError: LocalizedError, Equatable {
        case malformedEndpoint(String)
        case insecureEndpoint(String)

        var errorDescription: String? {
            switch self {
            case .malformedEndpoint(let text):
                return "“\(text)” is not a URL the transcription service can be reached at."
            case .insecureEndpoint(let host):
                return "A plain HTTP endpoint is only allowed for a local server, and "
                    + "“\(host)” is not one."
            }
        }
    }

    /// The region the person chose. An unknown or absent value is `.us`, not
    /// an error: a defaults file written by a later build, or by hand, must
    /// not stop the app from transcribing.
    static func region(defaults: UserDefaults = .standard) -> Region {
        guard let raw = defaults.string(forKey: regionKey), let region = Region(rawValue: raw)
        else { return .us }
        return region
    }

    /// Where the client speaks: the argument-domain endpoint when one is set,
    /// the region's own host otherwise.
    static func baseURL(defaults: UserDefaults = .standard) throws -> URL {
        guard let override = argument(endpointArgument, defaults: defaults) else {
            return region(defaults: defaults).base
        }
        guard let url = URL(string: override), let scheme = url.scheme?.lowercased(),
            let host = url.host, !host.isEmpty
        else { throw ConfigurationError.malformedEndpoint(override) }
        guard scheme == "http" || scheme == "https" else {
            throw ConfigurationError.malformedEndpoint(override)
        }
        // Plain HTTP for a loopback host only. C0's q3 measured that macOS
        // 26.5.1 does not block it from an ad-hoc-signed hardened-runtime
        // bundle with no ATS key at all, which is why `project.yml` carries
        // none — and this guard is what keeps that measurement from becoming
        // a licence to send a key over the open network in clear.
        guard scheme == "https" || isLoopback(host) else {
            throw ConfigurationError.insecureEndpoint(host)
        }
        return url
    }

    /// The `SecretStore` this process may use, and R6-9's whole decision in
    /// one function.
    ///
    /// With `-RCSecretFolder` set, a `FileStore` on that folder: a proof's
    /// own disposable directory. With no `-RCSecretFolder` but
    /// `-RCAssemblyAIEndpoint` set, an EMPTY `MemoryStore`: the app has been
    /// pointed at something that is not AssemblyAI, so the person's stored
    /// key is not opened at all and `RC_ASSEMBLYAI_KEY` is the only
    /// credential such a run can have. With neither, the person's own file
    /// under `AppSupport.directory` — the ONE line in this feature that names
    /// it. A machine with no Application Support folder answers an empty
    /// `MemoryStore` too, which reads as "no key is set".
    static func store(defaults: UserDefaults = .standard) -> any SecretStore {
        if let folder = argument(secretFolderArgument, defaults: defaults) {
            return FileStore(
                directory: URL(
                    fileURLWithPath: (folder as NSString).expandingTildeInPath,
                    isDirectory: true))
        }
        if argument(endpointArgument, defaults: defaults) != nil { return MemoryStore() }
        guard let directory = AppSupport.directory else { return MemoryStore() }
        return FileStore(directory: directory)
    }

    /// The credential: the store first, the environment second (R6-5, and
    /// R6-9 (d) amends the wording of that order and not the order). An empty
    /// environment variable is no credential, for `FileStore.read`'s reason.
    static func credential(
        store: any SecretStore,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> String? {
        if let stored = store.read() { return stored }
        guard let value = environment[environmentKey] else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    /// The three spellings of this machine, and only those three.
    /// `localhost.evil.com` resolves wherever its owner says and is not one
    /// of them; a bracketed IPv6 literal arrives from `URL.host` without its
    /// brackets, which is why `::1` is compared bare.
    static func isLoopback(_ host: String) -> Bool {
        let name = host.lowercased()
        return name == "127.0.0.1" || name == "localhost" || name == "::1"
    }

    /// A launch argument, from the ARGUMENT domain alone (R6-9 (c)). Reading
    /// it off `UserDefaults.standard.string(forKey:)` would let a value
    /// persisted in the app's own plist — by a previous session, by an
    /// installer, by anything running as the person — move where the key is
    /// read from, which is exactly what this rule forbids. Empty is absent.
    static func argument(_ key: String, defaults: UserDefaults) -> String? {
        let domain = defaults.volatileDomain(forName: UserDefaults.argumentDomain)
        guard let value = domain[key] as? String, !value.isEmpty else { return nil }
        return value
    }
}
import Foundation

/// What the assistant's session is configured with, resolved in one place:
/// the person's key (spec §11 AI-8), where the helper speaks (AI-13), the
/// model (AI-11) and the chat settings. Road map 12 A1.
///
/// **AI-13, the rule this file keeps.** A proof-launched app must never open
/// the person's stored key. `-RCSecretFolder <path>`, read from the ARGUMENT
/// domain alone (`AssemblyAIConfiguration.argument`, R6-9 (c)), names the
/// folder of `anthropic-key`; with `RC_ASSISTANT_BASE_URL` set and no
/// `-RCSecretFolder`, NO `FileStore` is built and `store()` answers an empty
/// `MemoryStore`, so an app pointed at a stand-in has the environment as its
/// only credential. The override is an environment variable, never a
/// default, because a variable cannot be persisted in the app's plist.
///
/// **`AppSupport.directory` is touched in exactly one line of this file**,
/// as in `AssemblyAIConfiguration.swift`, so "no proof reads the person's
/// folder" is checkable by reading.
///
/// **The key is never a tool argument, a launch argument or an answer**
/// (AI-8, R6-12): `credential` hands it to `AssistantSession.open`, which
/// writes it into the helper's `configure` on stdin and nowhere else. No tool
/// reads or writes the model (AI-11); it is a person's setting.
enum AssistantConfiguration {

    /// The store's file, beside AssemblyAI's `assemblyai-key`.
    static let keyFileName = "anthropic-key"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "ANTHROPIC_API_KEY"

    /// The helper's `api_base` (AI-13): the stand-in server's address in a
    /// proof. `protocol.ts` calls it "an environment variable of its own".
    static let baseURLVariable = "RC_ASSISTANT_BASE_URL"

    /// The persisted model, Settings' Assistant pane from A2.
    static let modelKey = "FrameJobAssistantModel"

    /// AI-11's default.
    static let defaultModel = "claude-opus-5-5"

    /// The helper's `ChatSettings` (`agent/src/protocol.ts`): the person's
    /// chat settings from Settings' Assistant pane (AI-20). A dev build's
    /// `-RCDevAssistantAutoCompact <tokens>` replaces the threshold, even
    /// with compaction off, for a proof (AI-18).
    static func settingsJSON(defaults: UserDefaults = .standard) -> [String: Any] {
        var json = AssistantChatSettings.load(from: defaults).helperJSON
        #if FRAMEJOB_DEV_TOOLS
        if let tokens = devAutoCompactTokens(defaults: defaults) {
            json["auto_compact_tokens"] = tokens
        }
        #endif
        return json
    }

    /// Why the base-URL override cannot be used, in the sentence the session
    /// refuses with.
    enum ConfigurationError: LocalizedError, Equatable {
        case malformedBase(String)
        case insecureBase(String)

        var errorDescription: String? {
            switch self {
            case .malformedBase(let text):
                return "RC_ASSISTANT_BASE_URL “\(text)” is not a URL the assistant can reach."
            case .insecureBase(let host):
                return "A plain HTTP RC_ASSISTANT_BASE_URL is only allowed for a local server, "
                    + "and “\(host)” is not one."
            }
        }
    }

    /// The `SecretStore` the assistant may use, and AI-13's whole decision in
    /// one function: `-RCSecretFolder`'s folder; else, with the base-URL
    /// override set, an EMPTY `MemoryStore`; else the person's own file under
    /// `AppSupport.directory`; else (no such folder) an empty `MemoryStore`.
    static func store(
        defaults: UserDefaults = .standard,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> any SecretStore {
        let folderKey = AssemblyAIConfiguration.secretFolderArgument
        if let folder = AssemblyAIConfiguration.argument(folderKey, defaults: defaults) {
            return FileStore(
                directory: URL(
                    fileURLWithPath: (folder as NSString).expandingTildeInPath,
                    isDirectory: true),
                name: keyFileName)
        }
        if let base = environment[baseURLVariable], !base.isEmpty { return MemoryStore() }
        guard let directory = AppSupport.directory else { return MemoryStore() }
        return FileStore(directory: directory, name: keyFileName)
    }

    /// The credential: the store first, the environment second (R6-9 (d)).
    /// An empty environment variable is no credential.
    static func credential(
        store: any SecretStore,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> String? {
        if let stored = store.read() { return stored }
        guard let value = environment[environmentKey] else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    /// The helper's `api_base`, or nil (the SDK's own host) when the override
    /// is unset or empty. Plain HTTP for a loopback host only (AI-13, R6-9).
    static func baseURL(
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> URL? {
        guard let text = environment[baseURLVariable], !text.isEmpty else { return nil }
        guard let url = URL(string: text), let scheme = url.scheme?.lowercased(),
            let host = url.host, !host.isEmpty,
            scheme == "http" || scheme == "https"
        else { throw ConfigurationError.malformedBase(text) }
        guard scheme == "https" || AssemblyAIConfiguration.isLoopback(host) else {
            throw ConfigurationError.insecureBase(host)
        }
        return url
    }

    /// The model the person chose, else AI-11's default. Blank is unset.
    static func model(defaults: UserDefaults = .standard) -> String {
        let chosen = defaults.string(forKey: modelKey)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard let chosen, !chosen.isEmpty else { return defaultModel }
        return chosen
    }
}

extension AssistantConfiguration {
    /// Posted by Settings' Assistant pane, and only by it, when the key is
    /// saved or removed, the model changes or the chat settings change. A key
    /// or model change ends each window's conversation, since a session keeps
    /// what it was opened with (road map 12 A2); a chat-settings change is
    /// written to each open session and ends nothing (AI-20).
    static let didChangeNotification = Notification.Name("FrameJobAssistantConfigurationDidChange")

    /// The notification's `userInfo` key; its value is "key", "model" or
    /// "settings".
    static let changeKey = "change"
}

/// The person's chat settings (spec §11 AI-20), Rasterize's two under
/// Frame Job's keys: end-of-turn compaction past a threshold (AI-9), and the
/// API's clearing of old tool results past the helper's fixed trigger. Kept
/// in `UserDefaults`; no tool reads or writes them (AI-11's reason).
struct AssistantChatSettings: Equatable {
    /// AI-9's threshold, and the one 300 000 in the app.
    static let defaultCompactTokens = 300_000
    static let compactTokensRange = 20_000...900_000
    /// `agent/src/main.ts`'s `CLEAR_TRIGGER_TOKENS` (the settings proof's CS1).
    static let clearTriggerTokens = 150_000
    /// Bool; absent = true.
    static let autoCompactKey = "FrameJobAssistantAutoCompact"
    /// Int; absent or outside the range = the default.
    static let autoCompactTokensKey = "FrameJobAssistantAutoCompactTokens"
    /// Bool; absent = false.
    static let clearToolResultsKey = "FrameJobAssistantClearToolResults"

    var autoCompact = true
    var autoCompactTokens = defaultCompactTokens
    var clearToolResults = false

    static func load(from defaults: UserDefaults = .standard) -> AssistantChatSettings {
        var settings = AssistantChatSettings()
        if defaults.object(forKey: autoCompactKey) != nil {
            settings.autoCompact = defaults.bool(forKey: autoCompactKey)
        }
        if defaults.object(forKey: autoCompactTokensKey) != nil {
            let tokens = defaults.integer(forKey: autoCompactTokensKey)
            if compactTokensRange.contains(tokens) { settings.autoCompactTokens = tokens }
        }
        settings.clearToolResults = defaults.bool(forKey: clearToolResultsKey)
        return settings
    }

    /// Writes all three keys.
    func save(to defaults: UserDefaults = .standard) {
        defaults.set(autoCompact, forKey: Self.autoCompactKey)
        defaults.set(autoCompactTokens, forKey: Self.autoCompactTokensKey)
        defaults.set(clearToolResults, forKey: Self.clearToolResultsKey)
    }

    /// `protocol.ts`'s `ChatSettings`: the threshold, or null when compaction
    /// is off, and whether old tool results are cleared.
    var helperJSON: [String: Any] {
        [
            "auto_compact_tokens": autoCompact ? autoCompactTokens as Any : NSNull(),
            "clear_tool_results": clearToolResults,
        ]
    }
}

#if FRAMEJOB_DEV_TOOLS
extension AssistantConfiguration {
    /// `-RCDevAssistantAutoCompact <tokens>` — a dev-only LAUNCH default
    /// (spec §11 AI-18): the end-of-turn compaction threshold a proof lowers,
    /// read from the argument domain alone. It replaces the person's
    /// threshold (`AssistantChatSettings`, AI-20).
    static let devAutoCompactArgument = "RCDevAssistantAutoCompact"

    /// The knob's tokens, or nil when it is absent. A value that is not a
    /// whole number of 1 or more is named on stderr and ignored.
    static func devAutoCompactTokens(defaults: UserDefaults) -> Int? {
        guard let raw = AssemblyAIConfiguration.argument(devAutoCompactArgument, defaults: defaults)
        else { return nil }
        if let tokens = Int(raw), tokens >= 1 { return tokens }
        let line = "\(devAutoCompactArgument) must be a whole number of tokens, 1 or more "
            + "(got \"\(raw)\"); it is ignored.\n"
        FileHandle.standardError.write(Data(line.utf8))
        return nil
    }
}
#endif

import Foundation

/// Where the person's AssemblyAI key lives, behind a protocol with three
/// verbs — and the two conformers this build ships: a `0600` file, and a
/// value in memory that never touches disk.
///
/// **Why a file and not the Keychain.** The Keychain is the better place and
/// was the plan. Road map 6 §3 q7 MEASURED what an ad-hoc signature does to a
/// login-keychain item: the next build blocks on a `SecurityAgent` modal for
/// a full twenty seconds — even with `kSecUseAuthenticationUIFail`, which
/// does not turn that ACL confirmation into a refusal — and its delete
/// answers `errSecInvalidOwnerEdit`, so the item cannot even be cleaned up by
/// the build that finds it. Every `make app` is a new ad-hoc signature, and
/// an agent-driven instance has nobody to click the modal. The
/// data-protection keychain is not a way out either: `SecItemAdd` there
/// answered `errSecMissingEntitlement` from an unsandboxed ad-hoc-signed app
/// with no keychain access group. **The file is the weaker choice and this
/// paragraph is the record of it**: it is readable by anything running as the
/// person, where a Keychain item is readable by one signed identity after one
/// confirmation. The protocol is what lets a build signed with a stable
/// Developer ID identity add a `KeychainStore` conformer and a one-time
/// migration later without touching anything above it (R6-5, road map 6 §5d).
///
/// **No proof ever reads the person's file.** `MemoryStore` is what a probe
/// gets, and R6-9's `-RCSecretFolder` is what moves a launched app's folder
/// somewhere disposable — `AssemblyAIConfiguration.store` is the one place
/// either is decided.
protocol SecretStore {
    /// The secret, or nil when there is none. Never throws: "no key set" is a
    /// state the sheet names, not an error (road map 6 §5d).
    func read() -> String?
    /// Replaces whatever is there. Throws when it cannot be written, because
    /// a Save button that said nothing and saved nothing is the failure this
    /// is for.
    func write(_ secret: String) throws
    /// Leaves nothing behind. Removing what is not there succeeds.
    func remove() throws
}

/// Why a store could not be written, in a sentence the Settings window can
/// show unchanged.
enum SecretStoreError: LocalizedError, Equatable {
    case unwritable(String)

    var errorDescription: String? {
        switch self {
        case .unwritable(let reason):
            return "The API key could not be saved: \(reason)"
        }
    }
}

/// The shipping conformer: one file, mode `0600`, in a directory created at
/// `0700`.
///
/// **The permissions are on the file from the moment it exists.** It is
/// created with `O_CREAT|O_EXCL` at mode `0600` under a temporary name and
/// `rename(2)`d into place — never written first and `chmod`ed after, which
/// would leave a window in which the key was world-readable, and never
/// through `Data.write`, whose `POSIXPermissions` would be applied to a file
/// that already existed. The rename is also what makes a replacement atomic:
/// a reader sees the old key or the new one, never a half-written file.
///
/// An EXISTING directory's mode is left alone. A person who tightened
/// `~/Library/Application Support/Frame Job/` themselves should keep what they
/// chose, and a directory the app did not create is not the app's to relax.
final class FileStore: SecretStore {

    /// The one spelling of AssemblyAI's file's name, and `name`'s default.
    static let fileName = "assemblyai-key"

    /// The folder the file sits in. `AssemblyAIConfiguration.store` and
    /// `AssistantConfiguration.store` resolve it — from `AppSupport.directory`
    /// for a person, from `-RCSecretFolder` for a proof — and nothing here
    /// reaches for a default of its own, so each key has exactly one line in
    /// the tree that can name a person's real folder (R6-9, AI-13).
    let directory: URL

    /// The file's name in `directory`: `fileName` for AssemblyAI's key,
    /// `AssistantConfiguration.keyFileName` (`anthropic-key`, spec §11 AI-8,
    /// AI-13) for the assistant's. Each store is one file; the temporary a
    /// write renames into place carries the same name.
    let name: String

    var fileURL: URL { directory.appendingPathComponent(name, isDirectory: false) }

    init(directory: URL, name: String = FileStore.fileName) {
        self.directory = directory
        self.name = name
    }

    /// The key, trimmed. An empty or whitespace-only file reads as NO key
    /// rather than as a key that is the empty string: a request with an empty
    /// `authorization` header would be refused by the service with the key
    /// sentence, and "no key is set" is the answer the person can act on.
    func read() -> String? {
        guard let data = try? Data(contentsOf: fileURL),
            let text = String(data: data, encoding: .utf8)
        else { return nil }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    func write(_ secret: String) throws {
        try makeDirectory()
        let temporary = directory.appendingPathComponent(
            ".\(name).\(UUID().uuidString)", isDirectory: false)
        let descriptor = temporary.withUnsafeFileSystemRepresentation { path -> Int32 in
            guard let path = path else { return -1 }
            return open(path, O_WRONLY | O_CREAT | O_EXCL, 0o600)
        }
        guard descriptor >= 0 else {
            throw SecretStoreError.unwritable(String(cString: strerror(errno)))
        }
        if let reason = writeAll(descriptor, Array(secret.utf8)) {
            close(descriptor)
            try? FileManager.default.removeItem(at: temporary)
            throw SecretStoreError.unwritable(reason)
        }
        close(descriptor)
        let moved = temporary.withUnsafeFileSystemRepresentation { from -> Int32 in
            guard let from = from else { return -1 }
            return fileURL.withUnsafeFileSystemRepresentation { to -> Int32 in
                guard let to = to else { return -1 }
                return rename(from, to)
            }
        }
        guard moved == 0 else {
            let reason = String(cString: strerror(errno))
            try? FileManager.default.removeItem(at: temporary)
            throw SecretStoreError.unwritable(reason)
        }
    }

    func remove() throws {
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return }
        do {
            try FileManager.default.removeItem(at: fileURL)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }

    /// The directory through `AppSupport.ensureDirectory` (#108): `mkdir(2)`
    /// at `0700` for each level that is absent, the intermediates included,
    /// and nothing at all for a level that is there. One mode, never
    /// `chmod`ed after.
    private func makeDirectory() throws {
        do {
            try AppSupport.ensureDirectory(directory)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }
}

/// Every byte of `bytes` to `descriptor`, or `strerror`'s sentence. A free
/// function because `write(2)` and `SecretStore.write(_:)` are the same name
/// and a method cannot call the system call without a module qualifier that
/// changes with the SDK.
///
/// **`EINTR` is retried and NOTHING else is.** A signal that landed while the
/// write was in progress is not a failure to write, and turning one into
/// `unwritable` loses a key the person had just typed and told them the disk
/// refused it (the reader review, road map 6 §10.13, H·3). Every other errno
/// is still the sentence it was.
///
/// **The retry is bounded**: at most `writeAllRetryLimit` interruptions per
/// call, and the next one answers `strerror(EINTR)`, so a writer that is
/// interrupted for ever cannot hold the caller for ever (#187, item 6).
///
/// **A write of 0 bytes is its own sentence**, at once and with no retry:
/// `write(2)` sets no `errno` when it answers 0, so `strerror(errno)` would
/// report whatever an earlier call left there (#187, item 6).
///
/// `using` is the probe's seam and nothing else: its default IS `write(2)`,
/// so the shipped path has one spelling, and a row can hand it a writer that
/// answers `EINTR` once before the real one runs.
func writeAll(
    _ descriptor: Int32, _ bytes: [UInt8],
    using write: (Int32, UnsafeRawPointer?, Int) -> Int = { Darwin.write($0, $1, $2) }
) -> String? {
    var offset = 0
    var interruptions = 0
    while offset < bytes.count {
        let written = bytes.withUnsafeBytes { buffer -> Int in
            guard let base = buffer.baseAddress else { return -1 }
            return write(descriptor, base + offset, buffer.count - offset)
        }
        if written > 0 {
            offset += written
            continue
        }
        if written == 0 { return "no bytes were written" }
        if errno == EINTR, interruptions < writeAllRetryLimit {
            interruptions += 1
            continue
        }
        return String(cString: strerror(errno))
    }
    return nil
}

/// How many `EINTR`s one `writeAll` call retries before it answers one.
let writeAllRetryLimit = 100

/// The probe's store, and the empty store R6-9 hands an app that was pointed
/// at a stand-in server. Nothing here touches disk, so no run of any
/// instrument can read or write the person's own key.
final class MemoryStore: SecretStore {
    private let lock = NSLock()
    private var secret: String?

    init(_ secret: String? = nil) {
        self.secret = REDACTED
    }

    func read() -> String? {
        lock.lock()
        defer { lock.unlock() }
        return secret
    }

    func write(_ secret: String) throws {
        lock.lock()
        self.secret = REDACTED
        lock.unlock()
    }

    func remove() throws {
        lock.lock()
        secret = nil
        lock.unlock()
    }
}

import Foundation

/// The two things that make an AssemblyAI client, resolved in one place: WHERE
/// it speaks (the base URL) and WHAT it says it is (the credential). R6-6 —
/// the protocol boundary is exactly this pair, so the stand-in server of road
/// map 6 §5i, the EU endpoint and a same-protocol relay are configurations
/// and not code.
///
/// **R6-9, the rule this file is the whole of.** A proof-launched app must
/// never open the person's stored key. `-RCSecretFolder <path>` overrides the
/// store's folder; with `-RCAssemblyAIEndpoint` set and no `-RCSecretFolder`,
/// NO `FileStore` is built at all and `store()` answers an empty
/// `MemoryStore`, so an app pointed at a stand-in has the environment as its
/// only credential. Both arguments are read ONLY out of the ARGUMENT domain,
/// so a persisted default — `UserDefaults`, a plist somebody wrote, a
/// leftover from another session — can redirect neither. Without that rule a
/// machine where the person had saved a real key would send it to a server
/// that writes every header to disk.
///
/// **`AppSupport.directory` is touched in exactly one line of this file** and
/// nowhere else in the feature, which is what makes "no proof reads the real
/// folder" checkable by reading rather than by hoping.
enum AssemblyAIConfiguration {

    /// The endpoint override, the `-RCRecordingFolder` idiom
    /// (`RecordingSetup.swift`). A whole base URL rather than a host, because
    /// the scheme is part of what is being overridden: the stand-in speaks
    /// plain HTTP.
    static let endpointArgument = "RCAssemblyAIEndpoint"

    /// The store-folder override (R6-9). A PATH, never a key — `ps` shows
    /// every launch argument to every user on the machine, which is the same
    /// reason R6-5 keeps the credential out of `transcribe`'s arguments.
    static let secretFolderArgument = "RCSecretFolder"

    /// The persisted region, the Settings window's popup.
    static let regionKey = "FrameJobAssemblyAIRegion"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "RC_ASSEMBLYAI_KEY"

    /// AssemblyAI's two data regions (road map 6 §2). A transcript made in
    /// one is not visible in the other, which is why this is a setting and
    /// not a fallback.
    enum Region: String, CaseIterable {
        case us
        case eu

        var base: URL {
            switch self {
            case .us: return Region.url("https://api.assemblyai.com")
            case .eu: return Region.url("https://api.eu.assemblyai.com")
            }
        }

        /// `URL(string:)` is optional because its input is usually somebody
        /// else's; these two are literals on the lines above. A parse that
        /// failed would be a typo there, and the fallback reaches no host at
        /// all — every request against it refuses, which is the safe
        /// direction: never a DIFFERENT server.
        private static func url(_ text: String) -> URL {
            URL(string: text) ?? URL(fileURLWithPath: "/dev/null")
        }

        var displayName: String {
            switch self {
            case .us: return "United States"
            case .eu: return "European Union"
            }
        }
    }

    /// Why a configured endpoint cannot be used, in a sentence the Settings
    /// window and a tool can both print.
    enum ConfigurationError: LocalizedError, Equatable {
        case malformedEndpoint(String)
        case insecureEndpoint(String)

        var errorDescription: String? {
            switch self {
            case .malformedEndpoint(let text):
                return "“\(text)” is not a URL the transcription service can be reached at."
            case .insecureEndpoint(let host):
                return "A plain HTTP endpoint is only allowed for a local server, and "
                    + "“\(host)” is not one."
            }
        }
    }

    /// The region the person chose. An unknown or absent value is `.us`, not
    /// an error: a defaults file written by a later build, or by hand, must
    /// not stop the app from transcribing.
    static func region(defaults: UserDefaults = .standard) -> Region {
        guard let raw = defaults.string(forKey: regionKey), let region = Region(rawValue: raw)
        else { return .us }
        return region
    }

    /// Where the client speaks: the argument-domain endpoint when one is set,
    /// the region's own host otherwise.
    static func baseURL(defaults: UserDefaults = .standard) throws -> URL {
        guard let override = argument(endpointArgument, defaults: defaults) else {
            return region(defaults: defaults).base
        }
        guard let url = URL(string: override), let scheme = url.scheme?.lowercased(),
            let host = url.host, !host.isEmpty
        else { throw ConfigurationError.malformedEndpoint(override) }
        guard scheme == "http" || scheme == "https" else {
            throw ConfigurationError.malformedEndpoint(override)
        }
        // Plain HTTP for a loopback host only. C0's q3 measured that macOS
        // 26.5.1 does not block it from an ad-hoc-signed hardened-runtime
        // bundle with no ATS key at all, which is why `project.yml` carries
        // none — and this guard is what keeps that measurement from becoming
        // a licence to send a key over the open network in clear.
        guard scheme == "https" || isLoopback(host) else {
            throw ConfigurationError.insecureEndpoint(host)
        }
        return url
    }

    /// The `SecretStore` this process may use, and R6-9's whole decision in
    /// one function.
    ///
    /// With `-RCSecretFolder` set, a `FileStore` on that folder: a proof's
    /// own disposable directory. With no `-RCSecretFolder` but
    /// `-RCAssemblyAIEndpoint` set, an EMPTY `MemoryStore`: the app has been
    /// pointed at something that is not AssemblyAI, so the person's stored
    /// key is not opened at all and `RC_ASSEMBLYAI_KEY` is the only
    /// credential such a run can have. With neither, the person's own file
    /// under `AppSupport.directory` — the ONE line in this feature that names
    /// it. A machine with no Application Support folder answers an empty
    /// `MemoryStore` too, which reads as "no key is set".
    static func store(defaults: UserDefaults = .standard) -> any SecretStore {
        if let folder = argument(secretFolderArgument, defaults: defaults) {
            return FileStore(
                directory: URL(
                    fileURLWithPath: (folder as NSString).expandingTildeInPath,
                    isDirectory: true))
        }
        if argument(endpointArgument, defaults: defaults) != nil { return MemoryStore() }
        guard let directory = AppSupport.directory else { return MemoryStore() }
        return FileStore(directory: directory)
    }

    /// The credential: the store first, the environment second (R6-5, and
    /// R6-9 (d) amends the wording of that order and not the order). An empty
    /// environment variable is no credential, for `FileStore.read`'s reason.
    static func credential(
        store: any SecretStore,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> String? {
        if let stored = store.read() { return stored }
        guard let value = environment[environmentKey] else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    /// The three spellings of this machine, and only those three.
    /// `localhost.evil.com` resolves wherever its owner says and is not one
    /// of them; a bracketed IPv6 literal arrives from `URL.host` without its
    /// brackets, which is why `::1` is compared bare.
    static func isLoopback(_ host: String) -> Bool {
        let name = host.lowercased()
        return name == "127.0.0.1" || name == "localhost" || name == "::1"
    }

    /// A launch argument, from the ARGUMENT domain alone (R6-9 (c)). Reading
    /// it off `UserDefaults.standard.string(forKey:)` would let a value
    /// persisted in the app's own plist — by a previous session, by an
    /// installer, by anything running as the person — move where the key is
    /// read from, which is exactly what this rule forbids. Empty is absent.
    static func argument(_ key: String, defaults: UserDefaults) -> String? {
        let domain = defaults.volatileDomain(forName: UserDefaults.argumentDomain)
        guard let value = domain[key] as? String, !value.isEmpty else { return nil }
        return value
    }
}
import Foundation

/// What the assistant's session is configured with, resolved in one place:
/// the person's key (spec §11 AI-8), where the helper speaks (AI-13), the
/// model (AI-11) and the chat settings. Road map 12 A1.
///
/// **AI-13, the rule this file keeps.** A proof-launched app must never open
/// the person's stored key. `-RCSecretFolder <path>`, read from the ARGUMENT
/// domain alone (`AssemblyAIConfiguration.argument`, R6-9 (c)), names the
/// folder of `anthropic-key`; with `RC_ASSISTANT_BASE_URL` set and no
/// `-RCSecretFolder`, NO `FileStore` is built and `store()` answers an empty
/// `MemoryStore`, so an app pointed at a stand-in has the environment as its
/// only credential. The override is an environment variable, never a
/// default, because a variable cannot be persisted in the app's plist.
///
/// **`AppSupport.directory` is touched in exactly one line of this file**,
/// as in `AssemblyAIConfiguration.swift`, so "no proof reads the person's
/// folder" is checkable by reading.
///
/// **The key is never a tool argument, a launch argument or an answer**
/// (AI-8, R6-12): `credential` hands it to `AssistantSession.open`, which
/// writes it into the helper's `configure` on stdin and nowhere else. No tool
/// reads or writes the model (AI-11); it is a person's setting.
enum AssistantConfiguration {

    /// The store's file, beside AssemblyAI's `assemblyai-key`.
    static let keyFileName = "anthropic-key"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "ANTHROPIC_API_KEY"

    /// The helper's `api_base` (AI-13): the stand-in server's address in a
    /// proof. `protocol.ts` calls it "an environment variable of its own".
    static let baseURLVariable = "RC_ASSISTANT_BASE_URL"

    /// The persisted model, Settings' Assistant pane from A2.
    static let modelKey = "FrameJobAssistantModel"

    /// AI-11's default.
    static let defaultModel = "claude-opus-5-5"

    /// The helper's `ChatSettings` (`agent/src/protocol.ts`): the person's
    /// chat settings from Settings' Assistant pane (AI-20). A dev build's
    /// `-RCDevAssistantAutoCompact <tokens>` replaces the threshold, even
    /// with compaction off, for a proof (AI-18).
    static func settingsJSON(defaults: UserDefaults = .standard) -> [String: Any] {
        var json = AssistantChatSettings.load(from: defaults).helperJSON
        #if FRAMEJOB_DEV_TOOLS
        if let tokens = devAutoCompactTokens(defaults: defaults) {
            json["auto_compact_tokens"] = tokens
        }
        #endif
        return json
    }

    /// Why the base-URL override cannot be used, in the sentence the session
    /// refuses with.
    enum ConfigurationError: LocalizedError, Equatable {
        case malformedBase(String)
        case insecureBase(String)

        var errorDescription: String? {
            switch self {
            case .malformedBase(let text):
                return "RC_ASSISTANT_BASE_URL “\(text)” is not a URL the assistant can reach."
            case .insecureBase(let host):
                return "A plain HTTP RC_ASSISTANT_BASE_URL is only allowed for a local server, "
                    + "and “\(host)” is not one."
            }
        }
    }

    /// The `SecretStore` the assistant may use, and AI-13's whole decision in
    /// one function: `-RCSecretFolder`'s folder; else, with the base-URL
    /// override set, an EMPTY `MemoryStore`; else the person's own file under
    /// `AppSupport.directory`; else (no such folder) an empty `MemoryStore`.
    static func store(
        defaults: UserDefaults = .standard,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> any SecretStore {
        let folderKey = AssemblyAIConfiguration.secretFolderArgument
        if let folder = AssemblyAIConfiguration.argument(folderKey, defaults: defaults) {
            return FileStore(
                directory: URL(
                    fileURLWithPath: (folder as NSString).expandingTildeInPath,
                    isDirectory: true),
                name: keyFileName)
        }
        if let base = environment[baseURLVariable], !base.isEmpty { return MemoryStore() }
        guard let directory = AppSupport.directory else { return MemoryStore() }
        return FileStore(directory: directory, name: keyFileName)
    }

    /// The credential: the store first, the environment second (R6-9 (d)).
    /// An empty environment variable is no credential.
    static func credential(
        store: any SecretStore,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> String? {
        if let stored = store.read() { return stored }
        guard let value = environment[environmentKey] else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    /// The helper's `api_base`, or nil (the SDK's own host) when the override
    /// is unset or empty. Plain HTTP for a loopback host only (AI-13, R6-9).
    static func baseURL(
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) throws -> URL? {
        guard let text = environment[baseURLVariable], !text.isEmpty else { return nil }
        guard let url = URL(string: text), let scheme = url.scheme?.lowercased(),
            let host = url.host, !host.isEmpty,
            scheme == "http" || scheme == "https"
        else { throw ConfigurationError.malformedBase(text) }
        guard scheme == "https" || AssemblyAIConfiguration.isLoopback(host) else {
            throw ConfigurationError.insecureBase(host)
        }
        return url
    }

    /// The model the person chose, else AI-11's default. Blank is unset.
    static func model(defaults: UserDefaults = .standard) -> String {
        let chosen = defaults.string(forKey: modelKey)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard let chosen, !chosen.isEmpty else { return defaultModel }
        return chosen
    }
}

extension AssistantConfiguration {
    /// Posted by Settings' Assistant pane, and only by it, when the key is
    /// saved or removed, the model changes or the chat settings change. A key
    /// or model change ends each window's conversation, since a session keeps
    /// what it was opened with (road map 12 A2); a chat-settings change is
    /// written to each open session and ends nothing (AI-20).
    static let didChangeNotification = Notification.Name("FrameJobAssistantConfigurationDidChange")

    /// The notification's `userInfo` key; its value is "key", "model" or
    /// "settings".
    static let changeKey = "change"
}

/// The person's chat settings (spec §11 AI-20), Rasterize's two under
/// Frame Job's keys: end-of-turn compaction past a threshold (AI-9), and the
/// API's clearing of old tool results past the helper's fixed trigger. Kept
/// in `UserDefaults`; no tool reads or writes them (AI-11's reason).
struct AssistantChatSettings: Equatable {
    /// AI-9's threshold, and the one 300 000 in the app.
    static let defaultCompactTokens = 300_000
    static let compactTokensRange = 20_000...900_000
    /// `agent/src/main.ts`'s `CLEAR_TRIGGER_TOKENS` (the settings proof's CS1).
    static let clearTriggerTokens = 150_000
    /// Bool; absent = true.
    static let autoCompactKey = "FrameJobAssistantAutoCompact"
    /// Int; absent or outside the range = the default.
    static let autoCompactTokensKey = "FrameJobAssistantAutoCompactTokens"
    /// Bool; absent = false.
    static let clearToolResultsKey = "FrameJobAssistantClearToolResults"

    var autoCompact = true
    var autoCompactTokens = defaultCompactTokens
    var clearToolResults = false

    static func load(from defaults: UserDefaults = .standard) -> AssistantChatSettings {
        var settings = AssistantChatSettings()
        if defaults.object(forKey: autoCompactKey) != nil {
            settings.autoCompact = defaults.bool(forKey: autoCompactKey)
        }
        if defaults.object(forKey: autoCompactTokensKey) != nil {
            let tokens = defaults.integer(forKey: autoCompactTokensKey)
            if compactTokensRange.contains(tokens) { settings.autoCompactTokens = tokens }
        }
        settings.clearToolResults = defaults.bool(forKey: clearToolResultsKey)
        return settings
    }

    /// Writes all three keys.
    func save(to defaults: UserDefaults = .standard) {
        defaults.set(autoCompact, forKey: Self.autoCompactKey)
        defaults.set(autoCompactTokens, forKey: Self.autoCompactTokensKey)
        defaults.set(clearToolResults, forKey: Self.clearToolResultsKey)
    }

    /// `protocol.ts`'s `ChatSettings`: the threshold, or null when compaction
    /// is off, and whether old tool results are cleared.
    var helperJSON: [String: Any] {
        [
            "auto_compact_tokens": autoCompact ? autoCompactTokens as Any : NSNull(),
            "clear_tool_results": clearToolResults,
        ]
    }
}

#if FRAMEJOB_DEV_TOOLS
extension AssistantConfiguration {
    /// `-RCDevAssistantAutoCompact <tokens>` — a dev-only LAUNCH default
    /// (spec §11 AI-18): the end-of-turn compaction threshold a proof lowers,
    /// read from the argument domain alone. It replaces the person's
    /// threshold (`AssistantChatSettings`, AI-20).
    static let devAutoCompactArgument = "RCDevAssistantAutoCompact"

    /// The knob's tokens, or nil when it is absent. A value that is not a
    /// whole number of 1 or more is named on stderr and ignored.
    static func devAutoCompactTokens(defaults: UserDefaults) -> Int? {
        guard let raw = AssemblyAIConfiguration.argument(devAutoCompactArgument, defaults: defaults)
        else { return nil }
        if let tokens = Int(raw), tokens >= 1 { return tokens }
        let line = "\(devAutoCompactArgument) must be a whole number of tokens, 1 or more "
            + "(got \"\(raw)\"); it is ignored.\n"
        FileHandle.standardError.write(Data(line.utf8))
        return nil
    }
